-- Importação e normalização das OS antigas de BJD/GOR (2025-2026)
-- Banco alvo: MySQL/MariaDB
-- Fontes: controles atuais e arquivos individuais dos dois ZIPs recebidos em 2026-10-02.
--
-- ESCOPO:
--   * 415 OS ausentes e classificadas como PRONTO para importação.
--   * 856 OS já existentes, sem id_plano_manutencao, com vínculo de plano determinístico.
--   * 2 registros existentes com número duplicado ficam fora da normalização automática.
--   * 144 OS ausentes em REVISAR não aparecem no estágio de importação.
--
-- SEGURANÇA:
--   * As duas operações ficam DESATIVADAS por padrão.
--   * As validações são executadas mesmo com as flags em 0.
--   * A normalização cria backup persistente antes de qualquer UPDATE.
--   * id_plano_item e id_plano_execucao permanecem NULL por falta de evidência histórica.
--   * Para executar, revise a planilha de auditoria e altere apenas a flag desejada para 1.

SET NAMES utf8mb4;
SET @lote_importacao = 'MIGRACAO_OS_ANTIGAS_BJD_GOR_202510_20261002';
SET @executar_importacao = 0;
SET @executar_normalizacao_planos = 0;

DROP TEMPORARY TABLE IF EXISTS stg_os_antigas_prontas_20261002;
CREATE TEMPORARY TABLE stg_os_antigas_prontas_20261002 (
    linha_origem INT NOT NULL,
    numero_os VARCHAR(30) NOT NULL,
    numero_si VARCHAR(30) NULL,
    id_subestacao INT NOT NULL,
    id_ativo INT NULL,
    id_grupo_ativo INT NULL,
    especie VARCHAR(100) NULL,
    numero_apr VARCHAR(50) NULL,
    instalacao VARCHAR(100) NULL,
    localizacao VARCHAR(100) NULL,
    complemento VARCHAR(100) NULL,
    origens TEXT NULL,
    defeito TEXT NULL,
    esquema_servicos VARCHAR(100) NOT NULL,
    prioridade VARCHAR(20) NOT NULL,
    responsavel VARCHAR(100) NULL,
    substituto VARCHAR(100) NULL,
    data_inicio_programado DATETIME NOT NULL,
    data_fim_programado DATETIME NOT NULL,
    descricao_servicos TEXT NOT NULL,
    observacoes TEXT NULL,
    causa_primaria TEXT NULL,
    causa_secundaria TEXT NULL,
    emissor TEXT NOT NULL,
    editado_por TEXT NULL,
    data_abertura_ss DATETIME NULL,
    data_inicio_execucao DATETIME NULL,
    data_fim_execucao DATETIME NULL,
    centro_custos VARCHAR(50) NULL,
    status VARCHAR(30) NOT NULL,
    id_plano_manutencao INT NULL,
    PRIMARY KEY (numero_os),
    KEY idx_stg_os_antigas_ativo (id_ativo),
    KEY idx_stg_os_antigas_grupo (id_grupo_ativo),
    KEY idx_stg_os_antigas_plano (id_plano_manutencao)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;












DROP TEMPORARY TABLE IF EXISTS stg_normalizacao_os_planos_20261002;
CREATE TEMPORARY TABLE stg_normalizacao_os_planos_20261002 (
    id_os INT NOT NULL,
    numero_os VARCHAR(30) NOT NULL,
    id_plano_manutencao INT NOT NULL,
    emissor_plano TEXT NOT NULL,
    PRIMARY KEY (id_os),
    UNIQUE KEY uq_stg_normalizacao_numero (numero_os)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;























-- Diagnóstico resumido dos dois estágios.
SELECT 'IMPORTAR' AS operacao, COUNT(*) AS quantidade FROM stg_os_antigas_prontas_20261002
UNION ALL
SELECT 'NORMALIZAR_PLANO', COUNT(*) FROM stg_normalizacao_os_planos_20261002;

CREATE TABLE IF NOT EXISTS backup_os_plano_historico_20261002 (
    id_os INT NOT NULL,
    numero_os VARCHAR(30) NOT NULL,
    id_plano_manutencao_anterior INT NULL,
    emissor_anterior TEXT NULL,
    editado_por_anterior TEXT NULL,
    id_plano_manutencao_novo INT NOT NULL,
    emissor_novo TEXT NOT NULL,
    criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id_os)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP PROCEDURE IF EXISTS executar_importacao_os_antigas_20261002;
DROP PROCEDURE IF EXISTS executar_normalizacao_os_planos_20261002;
DELIMITER $$
CREATE PROCEDURE executar_importacao_os_antigas_20261002(IN p_executar TINYINT)
importacao: BEGIN
    DECLARE v_qtd INT DEFAULT 0;
    DECLARE v_inseridos INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SELECT COUNT(*) INTO v_qtd FROM stg_os_antigas_prontas_20261002;
    IF v_qtd <> 415 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Importação abortada: quantidade do estágio divergente.';
    END IF;

    SELECT COUNT(*) INTO v_qtd
    FROM stg_os_antigas_prontas_20261002 s
    JOIN ordem_servico o ON BINARY o.numero_os = BINARY s.numero_os;
    IF v_qtd > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Importação abortada: uma ou mais OS já existem.';
    END IF;

    SELECT COUNT(*) INTO v_qtd
    FROM stg_os_antigas_prontas_20261002 s
    JOIN ordem_servico o ON BINARY o.numero_apr = BINARY s.numero_apr
    WHERE s.numero_apr IS NOT NULL AND s.numero_apr <> '';
    IF v_qtd > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Importação abortada: uma ou mais APR já existem.';
    END IF;

    SELECT COUNT(*) INTO v_qtd
    FROM stg_os_antigas_prontas_20261002 s
    LEFT JOIN subestacao se ON se.id_subestacao = s.id_subestacao
    LEFT JOIN ativo a ON a.id_ativo = s.id_ativo
    LEFT JOIN grupo_ativo g ON g.id_grupo_ativo = s.id_grupo_ativo
    WHERE se.id_subestacao IS NULL
       OR (s.id_ativo IS NOT NULL AND a.id_ativo IS NULL)
       OR (s.id_grupo_ativo IS NOT NULL AND g.id_grupo_ativo IS NULL)
       OR (s.id_ativo IS NULL AND s.id_grupo_ativo IS NULL)
       OR (a.id_ativo IS NOT NULL AND a.id_subestacao <> s.id_subestacao)
       OR (g.id_grupo_ativo IS NOT NULL AND g.id_subestacao <> s.id_subestacao);
    IF v_qtd > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Importação abortada: vínculo de subestação/ativo inválido.';
    END IF;

    SELECT COUNT(*) INTO v_qtd
    FROM stg_os_antigas_prontas_20261002 s
    LEFT JOIN ativo a ON a.id_ativo = s.id_ativo
    LEFT JOIN grupo_ativo g ON g.id_grupo_ativo = s.id_grupo_ativo
    LEFT JOIN plano_manutencao pm ON pm.id_plano_manutencao = s.id_plano_manutencao
    WHERE s.id_plano_manutencao IS NOT NULL
      AND (pm.id_plano_manutencao IS NULL
           OR pm.id_tipo_ativo <> COALESCE(a.id_tipo_ativo, g.id_tipo_ativo));
    IF v_qtd > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Importação abortada: plano incompatível com o tipo do ativo.';
    END IF;

    SELECT COUNT(*) INTO v_qtd
    FROM stg_os_antigas_prontas_20261002
    WHERE prioridade NOT REGEXP '^NIVEL_[1-6]$'
       OR TRIM(COALESCE(esquema_servicos, '')) = ''
       OR TRIM(COALESCE(descricao_servicos, '')) = ''
       OR TRIM(COALESCE(emissor, '')) = ''
       OR status NOT IN ('ABERTA', 'ENCERRADA')
       OR data_inicio_programado > data_fim_programado
       OR (data_inicio_execucao IS NOT NULL AND data_fim_execucao IS NOT NULL
           AND data_inicio_execucao > data_fim_execucao);
    IF v_qtd > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Importação abortada: campo obrigatório ou datas inválidas.';
    END IF;

    IF COALESCE(p_executar, 0) <> 1 THEN
        SELECT 'VALIDADO, NÃO EXECUTADO' AS resultado,
               '415 OS prontas; altere @executar_importacao para 1.' AS proxima_acao;
        LEAVE importacao;
    END IF;

    START TRANSACTION;
        numero_os, numero_si, id_subestacao, id_ativo, id_grupo_ativo,
        id_funcao_operacao, escopo_ativo, id_plano_manutencao,
        id_plano_item, id_plano_execucao, origem, especie, numero_apr,
        instalacao, localizacao, complemento, origens, defeito,
        esquema_servicos, prioridade, responsavel, substituto,
        data_inicio_programado, data_fim_programado, descricao_servicos,
        observacoes, causa_primaria, causa_secundaria, emissor, editado_por,
        data_abertura_ss, data_inicio_execucao, data_fim_execucao,
        centro_custos, status, criado_em
    )
    SELECT
        s.numero_os, s.numero_si, s.id_subestacao, s.id_ativo, s.id_grupo_ativo,
        COALESCE(a.id_funcao_operacao, g.id_funcao_operacao),
        CASE WHEN s.id_ativo IS NOT NULL THEN 'FASE' ELSE 'GRUPO' END,
        s.id_plano_manutencao, NULL, NULL, @lote_importacao,
        COALESCE(NULLIF(TRIM(a.especie), ''), NULLIF(TRIM(s.especie), ''), 'GERAL'),
        s.numero_apr, s.instalacao, s.localizacao, s.complemento,
        s.origens, s.defeito, s.esquema_servicos, s.prioridade,
        s.responsavel, s.substituto, s.data_inicio_programado,
        s.data_fim_programado, s.descricao_servicos, s.observacoes,
        s.causa_primaria, s.causa_secundaria, s.emissor, s.editado_por,
        s.data_abertura_ss, s.data_inicio_execucao, s.data_fim_execucao,
        s.centro_custos, s.status, CURRENT_TIMESTAMP
    FROM stg_os_antigas_prontas_20261002 s
    LEFT JOIN ativo a ON a.id_ativo = s.id_ativo
    LEFT JOIN grupo_ativo g ON g.id_grupo_ativo = s.id_grupo_ativo;

    SET v_inseridos = ROW_COUNT();
    IF v_inseridos <> 415 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Importação abortada: total inserido divergente.';
    END IF;
    COMMIT;
    SELECT 'IMPORTAÇÃO CONCLUÍDA' AS resultado, v_inseridos AS registros_inseridos;
END$$

CREATE PROCEDURE executar_normalizacao_os_planos_20261002(IN p_executar TINYINT)
normalizacao: BEGIN
    DECLARE v_qtd INT DEFAULT 0;
    DECLARE v_atualizados INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SELECT COUNT(*) INTO v_qtd FROM stg_normalizacao_os_planos_20261002;
    IF v_qtd <> 856 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Normalização abortada: quantidade do estágio divergente.';
    END IF;

    SELECT COUNT(*) INTO v_qtd
    FROM stg_normalizacao_os_planos_20261002 s
    LEFT JOIN ordem_servico o ON o.id_os = s.id_os AND BINARY o.numero_os = BINARY s.numero_os
    WHERE o.id_os IS NULL OR o.id_plano_manutencao IS NOT NULL;
    IF v_qtd > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Normalização abortada: OS ausente, divergente ou já vinculada.';
    END IF;

    SELECT COUNT(*) INTO v_qtd
    FROM stg_normalizacao_os_planos_20261002 s
    JOIN ordem_servico o ON o.id_os = s.id_os
    LEFT JOIN ativo a ON a.id_ativo = o.id_ativo
    LEFT JOIN grupo_ativo g ON g.id_grupo_ativo = o.id_grupo_ativo
    LEFT JOIN plano_manutencao pm ON pm.id_plano_manutencao = s.id_plano_manutencao
    WHERE pm.id_plano_manutencao IS NULL
       OR pm.id_tipo_ativo <> COALESCE(a.id_tipo_ativo, g.id_tipo_ativo);
    IF v_qtd > 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Normalização abortada: plano incompatível com o ativo.';
    END IF;

    IF COALESCE(p_executar, 0) <> 1 THEN
        SELECT 'VALIDADO, NÃO EXECUTADO' AS resultado,
               '856 OS existentes; altere @executar_normalizacao_planos para 1.' AS proxima_acao;
        LEAVE normalizacao;
    END IF;

    START TRANSACTION;
        id_os, numero_os, id_plano_manutencao_anterior, emissor_anterior,
        editado_por_anterior, id_plano_manutencao_novo, emissor_novo
    )
    SELECT o.id_os, o.numero_os, o.id_plano_manutencao, o.emissor,
           o.editado_por, s.id_plano_manutencao, s.emissor_plano
    FROM stg_normalizacao_os_planos_20261002 s
    JOIN ordem_servico o ON o.id_os = s.id_os;

    UPDATE ordem_servico o
    JOIN stg_normalizacao_os_planos_20261002 s ON s.id_os = o.id_os
    SET o.id_plano_manutencao = s.id_plano_manutencao,
        o.editado_por = CASE
            WHEN NULLIF(TRIM(COALESCE(o.editado_por, '')), '') IS NULL
                 AND NULLIF(TRIM(COALESCE(o.emissor, '')), '') IS NOT NULL
                 AND TRIM(o.emissor) NOT LIKE 'Plano #%'
            THEN TRIM(o.emissor)
            ELSE o.editado_por
        END,
        o.emissor = s.emissor_plano
    WHERE o.id_plano_manutencao IS NULL;

    SET v_atualizados = ROW_COUNT();
    IF v_atualizados <> 856 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Normalização abortada: total atualizado divergente.';
    END IF;
    COMMIT;
    SELECT 'NORMALIZAÇÃO CONCLUÍDA' AS resultado, v_atualizados AS registros_atualizados;
END$$
DELIMITER ;

CALL executar_importacao_os_antigas_20261002(@executar_importacao);
CALL executar_normalizacao_os_planos_20261002(@executar_normalizacao_planos);

DROP PROCEDURE IF EXISTS executar_importacao_os_antigas_20261002;
DROP PROCEDURE IF EXISTS executar_normalizacao_os_planos_20261002;

-- Conferências após eventual execução.
SELECT COUNT(*) AS total_lote_importado
FROM ordem_servico
WHERE BINARY origem = BINARY @lote_importacao;

SELECT COUNT(*) AS normalizacoes_pendentes
FROM stg_normalizacao_os_planos_20261002 s
JOIN ordem_servico o ON o.id_os = s.id_os
WHERE NOT (o.id_plano_manutencao <=> s.id_plano_manutencao)
   OR BINARY COALESCE(o.emissor, '') <> BINARY COALESCE(s.emissor_plano, '');

